  "Themes": "Temas",
  "This browser cannot do end-to-end encryption, so encrypted DMs are unavailable here.": "Este navegador no puede hacer cifrado de extremo a extremo, así que los DMs cifrados no están disponibles aquí.",
  "This console only runs the commands listed in \"help\". It cannot read or change anything on your computer.": "Esta consola solo ejecuta los comandos listados en \"help\". No puede leer ni cambiar nada de tu ordenador.",
  "This controller cannot rumble in this browser.": "Este mando no puede vibrar en este navegador.",
  "This device": "Este dispositivo",
  "This device has a different key than your account. It was probably reset somewhere else.": "Este dispositivo tiene una clave distinta a la de tu cuenta. Probablemente se restableció en otro lugar.",
  "This extension has no content scripts, so there is nothing Nebulix can run. Nebulix supports content-script extensions (ad blockers, site tweaks, themes), not ones that need a background page or popup.": "Esta extensión no tiene content scripts, así que no hay nada que Nebulix pueda ejecutar. Nebulix admite extensiones de content-script (bloqueadores de anuncios, ajustes de sitios, temas), no las que necesitan una página en segundo plano o un popup.",
  "This extension's content scripts are empty or missing.": "Los content scripts de esta extensión están vacíos o faltan.",
  "This happens when they reset their key or sign in on a new device. Compare the safety number before sharing anything private.": "Esto ocurre cuando restablecen su clave o inician sesión en un dispositivo nuevo. Compara el número de seguridad antes de compartir algo privado.",
  "This is the start of the channel. Say hi!": "Este es el comienzo del canal. ¡Saluda!",
  "This is the start of your encrypted chat.": "Este es el comienzo de tu chat cifrado.",
  "This lab failed to load": "Este laboratorio no se pudo cargar",
  "This measures the path between your browser and the Nebulix server. Running Nebulix on your own PC shows your machine speed; through a public link it shows your connection to the PC that hosts it.": "Esto mide el camino entre tu navegador y el servidor de Nebulix. Ejecutar Nebulix en tu propio PC muestra la velocidad de tu máquina; a través de un enlace público muestra tu conexión con el PC que lo aloja.",
  "This opens the real site directly in a new window — your IP and cookies will not be protected by Nebulix. Continue?": "Esto abre el sitio real directamente en una ventana nueva — tu IP y tus cookies no estarán protegidas por Nebulix. ¿Continuar?",
  "This page could not load": "Esta página no se pudo cargar",
  "This permanently deletes your account, cosmetics and coins. This cannot be undone.": "Esto elimina permanentemente tu cuenta, cosméticos y monedas. No se puede deshacer.",
  "This removes every channel and message. It cannot be undone.": "Esto elimina todos los canales y mensajes. No se puede deshacer.",
  "This section failed to load": "Esta sección no se pudo cargar",
  "This signs you out of every site in the proxy and reloads your tabs with a clean session. Continue?": "Esto cierra tu sesión en todos los sitios del proxy y recarga tus pestañas con una sesión limpia. ¿Continuar?",
  "This site does not use HTTPS": "Este sitio no usa HTTPS",
  "Through the proxy, sites see the address of the PC running Nebulix — not your own. Cookies, referrers and trackers are cleaned before they reach the site.": "A través del proxy, los sitios ven la dirección del PC que ejecuta Nebulix — no la tuya. Las cookies, referrers y rastreadores se limpian antes de llegar al sitio.",
  "Through the proxy, websites see the Nebulix server instead of your own computer, and your browsing stays inside Nebulix. These settings apply the next time you open or reload a tab.": "A través del proxy, los sitios web ven el servidor de Nebulix en lugar de tu propio ordenador, y tu navegación permanece dentro de Nebulix. Estos ajustes se aplican la próxima vez que abras o recargues una pestaña.",
