  "One tap — or your chosen key — instantly replaces this tab with a safe page. Back will not return to Nebulix. The button is the alert icon in the top bar; it also works while you are browsing a website.": "Un toque —o tu tecla— reemplaza al instante esta pestaña por una página segura. El botón Atrás no vuelve a Nebulix. El botón es el icono de alerta de la barra de arriba; también funciona mientras navegas por una web.",
  "Open blank tab": "Abrir pestaña en blanco",
  "Open in a blank tab": "Abrir en una pestaña en blanco",
  "Opened in a blank tab. You can close this one.": "Abierto en una pestaña en blanco. Puedes cerrar esta.",
  "Opens Nebulix inside an about:blank tab, so the address bar and history only show a blank page. Keep this Nebulix tab open in the background.": "Abre Nebulix dentro de una pestaña about:blank, así la barra de direcciones y el historial solo muestran una página en blanco. Deja esta pestaña de Nebulix abierta en segundo plano.",
  "Original": "Original",
  "Panic button": "Botón de pánico",
  "Panic — jump to a safe page ({k})": "Pánico — saltar a una página segura ({k})",
  "Pick the source language first to swap.": "Elige primero el idioma de origen para intercambiar.",
  "Pressed anywhere except while typing. The ` key is next to the 1 on most keyboards.": "Se pulsa en cualquier sitio salvo al escribir. La tecla ` está al lado del 1 en casi todos los teclados.",
  "Quick-exit key": "Tecla de salida rápida",
  "Show a different name and icon on the browser tab, so a glance at your tabs does not reveal Nebulix.": "Muestra otro nombre e icono en la pestaña del navegador, para que una ojeada a tus pestañas no delate Nebulix.",
  "Show original": "Ver original",
  "Show the tab as": "Mostrar la pestaña como",
