  "Test: jumping in 1 second…": "Prueba: saltando en 1 segundo…",
  "To": "A",
  "To translate, this message is sent to the translator (your Nebulix server and, if no AI is connected, MyMemory). It leaves the end-to-end encryption for that moment. Continue?": "Para traducir, este mensaje se envía al traductor (tu servidor de Nebulix y, si no hay IA conectada, MyMemory). Sale del cifrado de extremo a extremo en ese momento. ¿Continuar?",
  "Translate": "Traducir",
