  "Every update to Nebulix, newest first. We ship improvements all the time.": "Cada actualización de Nebulix, de la más nueva a la más antigua. Lanzamos mejoras continuamente.",
  // ---- Nebulix 3 ----
  "Welcome tour": "Tour de bienvenida",
  "Welcome to Nebulix": "Te damos la bienvenida a Nebulix",
  "A quick tour of the essentials. It takes about a minute — you can skip it any time.": "Un tour rápido por lo esencial. Dura un minuto y puedes saltarlo cuando quieras.",
  "Your sidebar": "Tu barra lateral",
  "Every part of Nebulix lives here, grouped into Social, Play and Create. Press [ to collapse it.": "Todo Nebulix está aquí, agrupado en Social, Jugar y Crear. Pulsa [ para plegarla.",
  "Ctrl K opens a command bar: jump to any page, find people, open a website or run an action.": "Ctrl K abre una barra de comandos: salta a cualquier página, busca gente, abre una web o ejecuta una acción.",
  "Go anywhere": "Ve a cualquier sitio",
  "Type a website or a search here. Everything opens through the private, isolated proxy.": "Escribe aquí una web o una búsqueda. Todo se abre a través del proxy privado y aislado.",
  "All the apps": "Todas las apps",
  "Community, encrypted messages, squads, events, music, games, notes, the translator and more.": "Comunidad, mensajes cifrados, squads, eventos, música, juegos, notas, el traductor y más.",
  "In a hurry? One tap jumps the whole tab to a safe page. Set it up (and a disguise) in Settings → Safety.": "¿Con prisa? Un toque lleva toda la pestaña a una página segura. Configúralo (y un camuflaje) en Ajustes → Seguridad.",
  "Mentions, messages, friend requests, invites and reminders collect here.": "Aquí se reúnen menciones, mensajes, solicitudes de amistad, invitaciones y recordatorios.",
  "Claim the daily reward and spend coins on profile cosmetics in the Market. Play money only.": "Reclama la recompensa diaria y gasta monedas en cosméticos de perfil en el Mercado. Solo dinero ficticio.",
  "Your account": "Tu cuenta",
  "Profile, status, light or dark mode, Do not disturb and settings.": "Perfil, estado, modo claro u oscuro, No molestar y ajustes.",
  "You are ready": "Todo listo",
  "Press ? any time for keyboard shortcuts. More tours are in the account menu and in Ctrl K.": "Pulsa ? en cualquier momento para ver los atajos de teclado. Hay más tours en el menú de la cuenta y en Ctrl K.",
  "Community tour": "Tour de la comunidad",
  "Your servers. Create your own or join one with an invite code.": "Tus servidores. Crea el tuyo o únete a uno con un código de invitación.",
  "Channels": "Canales",
  "Text channels. People talking in a channel's voice room show up under it.": "Canales de texto. Quien esté hablando en la sala de voz de un canal aparece debajo.",
  "Every channel has a voice room for up to 8 people. Ctrl+Shift+M mutes you from any page.": "Cada canal tiene una sala de voz para hasta 8 personas. Ctrl+Mayús+M te silencia desde cualquier página.",
  "Send messages, images, polls and voice notes. Type / for commands like /roll or /poll.": "Envía mensajes, imágenes, encuestas y notas de voz. Escribe / para comandos como /roll o /poll.",
  "Browser tour": "Tour del navegador",
  "Type an address or a search. Pages load through the proxy, so the site never sees your real connection.": "Escribe una dirección o una búsqueda. Las páginas cargan por el proxy, así que el sitio nunca ve tu conexión real.",
  "Toolbar": "Barra de herramientas",
  "Back, forward, the ad & tracker shield, bookmarks, and a menu to send the page to a friend.": "Atrás, adelante, el escudo contra anuncios y rastreadores, marcadores y un menú para enviar la página a un amigo.",
  "Messages tour": "Tour de mensajes",
  "Chats and friends": "Chats y amigos",
  "Add friends by username. Requests and blocked people are in the tabs.": "Añade amigos por nombre de usuario. Las solicitudes y los bloqueados están en las pestañas.",
  "Messages, images and voice notes are encrypted on your device. Open a chat to share your screen, too.": "Los mensajes, imágenes y notas de voz se cifran en tu dispositivo. Abre un chat para compartir también tu pantalla.",
  "Squads tour": "Tour de squads",
  "Start a squad": "Crea un squad",
  "Say what you are playing and how many players you need. Slots fill up live.": "Di a qué juegas y cuántos jugadores necesitas. Los huecos se llenan en directo.",
  "Filters": "Filtros",
  "Show squads with space, yours, or the ones using voice chat.": "Muestra squads con hueco, los tuyos o los que usan chat de voz.",
