  "Two-step verification": "Verificación en dos pasos",
  "Enter the 6-digit code from your authenticator app. You can also use one of your backup codes.": "Escribe el código de 6 dígitos de tu app autenticadora. También puedes usar uno de tus códigos de respaldo.",
  "Copied": "Copiado",
  "Save your backup codes": "Guarda tus códigos de respaldo",
  "Each code works once if you lose your phone. Keep them somewhere safe: they will not be shown again.": "Cada código sirve una vez si pierdes el móvil. Guárdalos en un lugar seguro: no se volverán a mostrar.",
  "I saved them": "Ya los guardé",
