  "Set up your authenticator app": "Configura tu app autenticadora",
  "1. Open an authenticator app (Google Authenticator, Microsoft Authenticator, Aegis, 2FAS…) and add an account by entering this key:": "1. Abre una app autenticadora (Google Authenticator, Microsoft Authenticator, Aegis, 2FAS…) y añade una cuenta escribiendo esta clave:",
