  "For games that need IndexedDB, service workers or that fail in the sandbox. It runs on the separate games domain, so it still cannot see anyone’s account.": "Para juegos que necesitan IndexedDB o service workers, o que fallan en modo aislado. Se ejecuta en el dominio de juegos aparte, así que tampoco puede ver la cuenta de nadie.",
