  "Paste the API key": "Pega la clave de la API",
  "Choose what powers Nova. \"Automatic\" uses your Claude key if there is one, otherwise a local Ollama model if it is running, otherwise the built-in helper.": "Elige qué IA usa Nova. «Automático» usa tu clave si hay una; si no, Ollama si está en marcha; si no, la IA gratuita en línea.",
  "Works right away with no account: GPT-OSS 20B from Pollinations. The free tier allows about one reply every 45 seconds for the whole server, so with several people at once Nova falls back to the built-in helper. For real use, add a free key below.": "Funciona al momento y sin cuenta: GPT-OSS 20B de Pollinations. El plan gratuito permite una respuesta cada 45 segundos para todo el servidor, así que con varias personas a la vez Nova pasa al asistente básico. Para uso real, añade una clave gratuita aquí abajo.",
  "Available": "Disponible",
