  "Free API with a key (recommended)": "API gratuita con clave (recomendado)",
  "Create a free key on one of these sites (it takes a minute), pick it here and paste the key. Groq is the fastest; Gemini and OpenRouter also have free plans. The key stays on this server.": "Crea una clave gratuita en una de estas webs (tarda un minuto), elígela aquí y pega la clave. Groq es la más rápida; Gemini y OpenRouter también tienen planes gratis. La clave se queda en este servidor.",
