  "Run test": "Probar",
  "Nebulix VPN protects what you browse inside Nebulix. It does not change the connection of other apps or the rest of your device.": "Nebulix VPN protege lo que navegas dentro de Nebulix. No cambia la conexión de otras apps ni del resto de tu dispositivo.",
