  "Copy all": "Copiar todos",
  "Delete this link?": "¿Borrar este link?",
  "You have not created links yet.": "Aún no has creado links.",
  "…or paste a Nebulix link (for example a game or a profile)": "…o pega un link de Nebulix (por ejemplo de un juego o un perfil)",
  "Link name (optional, e.g. my-game)": "Nombre del link (opcional, p. ej. mi-juego)",
  "Your link works on every address:": "Tu link funciona en todas las direcciones:",
  "All the addresses of Nebulix. They are the same server: your account, coins and data are the same on every one.": "Todas las direcciones de Nebulix. Son el mismo servidor: tu cuenta, tus monedas y tus datos son los mismos en todas.",
  "Nebulix addresses": "Direcciones de Nebulix",
  "If one address does not open on your network, try another. You may need to sign in again on a new address.": "Si una dirección no abre en tu red, prueba otra. Puede que tengas que volver a iniciar sesión en una dirección nueva.",
  "Link generator": "Generador de links",
  "Make a short link to any page of Nebulix. It works on every address, and you can open it in a hidden tab.": "Crea un link corto a cualquier página de Nebulix. Funciona en todas las direcciones y puedes abrirlo en una pestaña oculta.",
  "Generate": "Generar",
  "Your links": "Tus links",
  "Studio design": "Diseño Studio",
  "A calm, flat look: neutral greys, one accent colour, no glows or animated backgrounds. It replaces your theme colours while it is on.": "Un aspecto tranquilo y plano: grises neutros, un solo color de acento y sin brillos ni fondos animados. Sustituye los colores de tu tema mientras está activado.",
  "Studio design on": "Diseño Studio activado",
  "Studio design off": "Diseño Studio desactivado",
  "More addresses + link generator": "Más direcciones + generador de links",
  "One switch for maximum privacy while you browse inside Nebulix.": "Un solo botón para la máxima privacidad mientras navegas en Nebulix.",
  "nebulix-play, nebulix-zone and nebulix-hq: the same Nebulix. Make short links that work on all of them.": "nebulix-play, nebulix-zone y nebulix-hq: el mismo Nebulix. Crea links cortos que funcionan en todas.",
  "Virtual machine manager": "Gestor de máquinas virtuales",
  "Create machines, virtual disks and snapshots. New: Damn Small Linux, OpenBSD and Oberon.": "Crea máquinas, discos virtuales e instantáneas. Nuevos: Damn Small Linux, OpenBSD y Oberon.",
  "Windows is not included: use an ISO you have a licence for. The image stays in this browser and is read in pieces, so even big ISOs work.": "Windows no viene incluido: usa una ISO de la que tengas licencia. La imagen se queda en este navegador y se lee por partes, así que funcionan hasta las ISO grandes.",
  "Max 8 GB": "Máximo 8 GB",
  "CD/DVD first": "Primero CD/DVD",
  "Hard disk first": "Primero disco duro",
  "Floppy first": "Primero disquete",
  "ACPI (needed by Windows XP and newer)": "ACPI (lo necesitan Windows XP y posteriores)",
  "After installing an OS from the CD, switch to “Hard disk first”. Up to {m} MB of memory: big values need a powerful computer.": "Después de instalar un sistema desde el CD, cambia a «Primero disco duro». Hasta {m} MB de memoria: los valores altos necesitan un ordenador potente.",
  "Capture the mouse (Esc releases it)": "Capturar el ratón (Esc lo suelta)",
  "Change CD": "Cambiar CD",
  "CD": "CD",
  "CD inserted: {n}": "CD insertado: {n}",
  "CD/DVD drive": "Unidad de CD/DVD",
  "Insert another ISO (for example drivers or programs) or eject the current one.": "Inserta otra ISO (por ejemplo, de drivers o programas) o expulsa la actual.",
  "Eject": "Expulsar",
  "CD ejected": "CD expulsado",
  "Insert ISO…": "Insertar ISO…",
  "Retro consoles": "Consolas retro",
  "Play your own game files from classic consoles. Gamepad, keyboard and touch controls, save states and fast-forward are built in.": "Juega con tus propios archivos de juegos de consolas clásicas. Incluye mando, teclado y controles táctiles, guardado rápido y avance rápido.",
  "Add games": "Añadir juegos",
  "The games domain is not configured on this server, so the emulator cannot start.": "El dominio de juegos no está configurado en este servidor, así que el emulador no puede arrancar.",
  "played {d}": "jugado el {d}",
  "Remove “{n}” from this browser?": "¿Quitar «{n}» de este navegador?",
  "Add game files (.nes, .sfc, .gba, .n64, .md, PlayStation .cue/.chd…). Use games you own or free homebrew games.": "Añade archivos de juegos (.nes, .sfc, .gba, .n64, .md, PlayStation .cue/.chd…). Usa juegos que tengas o juegos homebrew gratuitos.",
  "Supported systems": "Sistemas compatibles",
  "Emulation by EmulatorJS (open source, GPLv3). Nebulix does not provide games: only play files you are allowed to use. Free, legal homebrew games are on sites like itch.io.": "Emulación con EmulatorJS (código abierto, GPLv3). Nebulix no proporciona juegos: usa solo archivos que tengas derecho a usar. Hay juegos homebrew gratuitos y legales en webs como itch.io.",
  "Unknown game type: {n}": "Tipo de juego desconocido: {n}",
  "Too big: {n}": "Demasiado grande: {n}",
  "{n} games added": "{n} juegos añadidos",
  "Cloud gaming": "Juego en la nube",
  "Big games streamed from powerful servers to any device — even a school laptop or a phone. You only need a good connection.": "Juegos grandes emitidos desde servidores potentes a cualquier dispositivo, incluso un portátil del instituto o un móvil. Solo necesitas una buena conexión.",
  "Streaming services": "Servicios de streaming",
  "Free tier": "Plan gratis",
  "These services are run by other companies and need their own account. They open in a new tab because they stream video directly to your browser. For the best result: wired connection or 5 GHz Wi-Fi, 15+ Mbps, and a gamepad.": "Estos servicios son de otras empresas y necesitan su propia cuenta. Se abren en una pestaña nueva porque emiten el vídeo directamente a tu navegador. Para ir bien: conexión por cable o wifi de 5 GHz, más de 15 Mbps y un mando.",
  "Play now in Nebulix": "Juega ya en Nebulix",
  "NES, SNES, GBA, N64, PlayStation and more, with gamepad and save states.": "NES, SNES, GBA, N64, PlayStation y más, con mando y guardado rápido.",
  "Windows in virtual machines": "Windows en máquinas virtuales",
  "Up to 2 GB of RAM, 32 GB disks and templates for Windows 98, 2000, XP and ReactOS.": "Hasta 2 GB de RAM, discos de 32 GB y plantillas para Windows 98, 2000, XP y ReactOS.",
  "Which console is “{n}” for?": "¿De qué consola es «{n}»?",
